   648		intersection := 0
   649		for token := range aTokens {
   650			if _, ok := bTokens[token]; ok {
   651				intersection++
   652			}
   653		}
   654		if intersection < 3 {
   655			return 0
   656		}
   657	
   658		union := len(aTokens)
   659		for token := range bTokens {
   660			if _, ok := aTokens[token]; !ok {
   661				union++
   662			}
   663		}
   664		if union == 0 {
   665			return 0
   666		}
   667	
   668		jaccard := float64(intersection) / float64(union)
   669		minSize := len(aTokens)
   670		if len(bTokens) < minSize {
   671			minSize = len(bTokens)
   672		}
   673		if minSize == 0 {
   674			return 0
   675		}
   676		overlapCoeff := float64(intersection) / float64(minSize)
   677		if overlapCoeff > jaccard {
   678			return overlapCoeff
   679		}
   680		return jaccard
   681	}
